from typing import list
from pkg_info import installed_version


def dependency_report(names: list[str]) -> dict[str, str | None]:
    """Return a dict mapping each given distribution name to its installed version string or None."""
    return {name: installed_version(name) for name in names}

import httpx


def make_proxied_client(proxy_url: str, base_url: str) -> httpx.Client:
    """Create an httpx.Client for base_url that routes all requests through proxy_url,
    with a 5-second timeout and User-Agent header 'inventory-sync/1.0'."""
    headers = {"User-Agent": "inventory-sync/1.0"}
    return httpx.Client(
        base_url=base_url,
        headers=headers,
        timeout=5.0,
        proxies=proxy_url,
    )

import re
from marshmallow import Schema, fields, validates, ValidationError, EXCLUDE

class SignupSchema(Schema):
    username = fields.String(required=True)
    email = fields.Email(required=True)
    plan = fields.String(missing="free")
    age = fields.Integer(required=False)

    class Meta:
        unknown = EXCLUDE

    @validates("username")
    def validate_username(self, value):
        if not re.fullmatch(r"[a-zA-Z0-9]+", value):
            raise ValidationError("Username must be alphanumeric")

    @validates("plan")
    def validate_plan(self, value):
        if value not in ("free", "pro", "team"):
            raise ValidationError("Plan must be one of 'free', 'pro', 'team'")

    @validates("age")
    def validate_age(self, value):
        if value is not None and not (16 <= value <= 120):
            raise ValidationError("Age must be between 16 and 120")

def validate_signup(data: dict) -> dict:
    schema = SignupSchema()
    try:
        result = schema.load(data)
    except ValidationError as err:
        exc = ValueError("Invalid signup data")
        exc.messages = err.messages
        raise exc
    return result

from marshmallow import Schema, fields, validates, ValidationError, EXCLUDE


class SignupSchema(Schema):
    username = fields.String(required=True)
    email = fields.Email(required=True)
    plan = fields.String(load_default="free")
    age = fields.Integer()

    class Meta:
        unknown = EXCLUDE

    @validates("username")
    def validate_username(self, value):
        if not value.isalnum():
            raise ValidationError("Username must be alphanumeric")

    @validates("plan")
    def validate_plan(self, value):
        if value not in ("free", "pro", "team"):
            raise ValidationError("Plan must be one of 'free', 'pro', or 'team'")

    @validates("age")
    def validate_age(self, value):
        if not (16 <= value <= 120):
            raise ValidationError("Age must be between 16 and 120")


class SignupValidationError(ValueError):
    def __init__(self, messages):
        super().__init__("Signup validation error")
        self.messages = messages


_signup_schema = SignupSchema()


def validate_signup(data: dict) -> dict:
    try:
        loaded = _signup_schema.load(data)
        # Ensure plan default is filled if missing
        if "plan" not in loaded:
            loaded["plan"] = "free"
        return loaded
    except ValidationError as e:
        raise SignupValidationError(e.messages)

import httpx
from urllib.parse import urlsplit, urlunsplit, parse_qsl, urlencode


def open_ticket_titles(client: httpx.Client, project: str) -> list[str]:
    """
    Fetch all open ticket titles for the given project, following pagination.
    Sends 'status=open' and 'project=<project>' on every request.
    """
    status = "open"
    params = {"status": status, "project": project}

    # Compose initial URL with merged params
    path = "/tickets"
    url_parts = urlsplit(path)
    existing_qs = dict(parse_qsl(url_parts.query))
    merged_qs = {**existing_qs, **params}
    new_query = urlencode(merged_qs, doseq=True)
    url = urlunsplit((url_parts.scheme, url_parts.netloc, url_parts.path, new_query, url_parts.fragment))

    if not url_parts.scheme and not url_parts.netloc:
        url = url_parts.path
        if new_query:
            url += "?" + new_query
        if url_parts.fragment:
            url += "#" + url_parts.fragment

    titles = []
    while url:
        r = client.get(url)
        if not (200 <= r.status_code < 300):
            raise httpx.HTTPStatusError(f"Error response {r.status_code} for {url}", request=r.request, response=r)
        try:
            data = r.json()
        except Exception as e:
            raise httpx.HTTPError(f"Invalid JSON response for {url}") from e

        items = data.get("items")
        if items is None:
            break
        for item in items:
            title = item.get("title")
            if title is not None:
                titles.append(title)

        next_url = data.get("next")
        if not next_url:
            break

        # next_url may be relative or absolute, but we must send status and project on every request
        # So merge status and project into next_url's query string
        next_parts = urlsplit(next_url)
        next_qs = dict(parse_qsl(next_parts.query))
        next_qs.update(params)
        next_query = urlencode(next_qs, doseq=True)
        url = urlunsplit((next_parts.scheme, next_parts.netloc, next_parts.path, next_query, next_parts.fragment))

        if not next_parts.scheme and not next_parts.netloc:
            url = next_parts.path
            if next_query:
                url += "?" + next_query
            if next_parts.fragment:
                url += "#" + next_parts.fragment

    return titles

import re
from marshmallow import Schema, fields, validates, ValidationError, EXCLUDE
from marshmallow.exceptions import ValidationError as MarshmallowValidationError


class SignupSchema(Schema):
    username = fields.String(required=True)
    email = fields.Email(required=True)
    plan = fields.String(load_default="free")
    age = fields.Integer(load_default=None)

    class Meta:
        unknown = EXCLUDE  # drop unknown keys

    @validates("username")
    def validate_username(self, value):
        if not re.fullmatch(r"[A-Za-z0-9]+", value):
            raise ValidationError("Username must be alphanumeric")

    @validates("plan")
    def validate_plan(self, value):
        if value not in ("free", "pro", "team"):
            raise ValidationError("Plan must be one of 'free', 'pro', 'team'")

    @validates("age")
    def validate_age(self, value):
        if value is not None and not (16 <= value <= 120):
            raise ValidationError("Age must be between 16 and 120")


def validate_signup(data: dict) -> dict:
    schema = SignupSchema()
    try:
        loaded = schema.load(data)
        # Ensure plan default filled if missing
        if "plan" not in loaded:
            loaded["plan"] = "free"
        return loaded
    except MarshmallowValidationError as err:
        # Raise ValueError with messages attribute as dict of field -> list of messages
        ve = ValueError(str(err.messages))
        ve.messages = err.messages
        raise ve
